import { apiClient, unwrap, type BffResponse } from '../api';

export interface AnnualBudgetPlanListItem {
  id: string;
  year: number;
  accountCode: string;
  jobCode: string;
  amount: number;
  amountFc: number;
}

export interface AnnualBudgetPlanPage {
  items: AnnualBudgetPlanListItem[];
  totalCount: number;
  page: number;
  pageSize: number;
}

export interface AnnualBudgetPlanWriteBody {
  year: number;
  accountCode: string;
  jobCode: string;
  amount: number;
  amountFc: number;
}

export interface AnnualBudgetPlanUpdateBody extends AnnualBudgetPlanWriteBody {
  id: string;
}

export async function listAnnualBudgetPlans(query: {
  year: number;
  page: number;
  pageSize: number;
  search?: string;
}): Promise<AnnualBudgetPlanPage> {
  const qs = new URLSearchParams();
  qs.set('year', String(query.year));
  qs.set('page', String(query.page));
  qs.set('pageSize', String(query.pageSize));
  const search = query.search?.trim() ?? '';
  if (search) qs.set('search', search);
  const res = await apiClient.get<BffResponse<AnnualBudgetPlanPage>>(
    `/accounting/annual-budget-plans?${qs.toString()}`,
  );
  return unwrap(res);
}

export async function createAnnualBudgetPlan(
  body: AnnualBudgetPlanWriteBody,
): Promise<AnnualBudgetPlanListItem> {
  const res = await apiClient.post<BffResponse<AnnualBudgetPlanListItem>>(
    '/accounting/annual-budget-plans',
    body,
  );
  return unwrap(res);
}

export async function updateAnnualBudgetPlan(
  id: string,
  body: AnnualBudgetPlanUpdateBody,
): Promise<AnnualBudgetPlanListItem> {
  const res = await apiClient.put<BffResponse<AnnualBudgetPlanListItem>>(
    `/accounting/annual-budget-plans/${encodeURIComponent(id)}`,
    body,
  );
  return unwrap(res);
}

export async function deleteAnnualBudgetPlan(id: string): Promise<boolean> {
  const res = await apiClient.delete<BffResponse<boolean>>(
    `/accounting/annual-budget-plans/${encodeURIComponent(id)}`,
  );
  return unwrap(res);
}
